function aquaSeed(seed){return()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296}}
function aquaWave(c,w,h,y,amp,fill,phase=0){c.beginPath();c.moveTo(0,h);c.lineTo(0,y+Math.sin(phase)*amp);for(let i=0;i<=32;i++){let x=i/32*w;c.lineTo(x,y+Math.sin(i*.31+phase)*amp+Math.sin(i*.68+phase)*amp*.32)}c.lineTo(w,h);c.closePath();c.fillStyle=fill;c.fill()}
