function aquaPlant(c,x,y,s,t,col){c.save();c.translate(x,y);c.scale(s,s);for(let i=0;i<4;i++){let ex=(i-1.5)*17+Math.sin(t*.9+i)*7,ey=-46-(i%3)*17;const g=aquaLinear(c,0,ey,0,0,[[0,'#adf6a9'],[.42,col],[1,'#17636b']]);c.beginPath();c.moveTo((i-1.5)*5,0);c.bezierCurveTo(ex-20,-20,ex+13,ey*.68,ex,ey);c.bezierCurveTo(ex-7,ey*.58,ex+19,-13,(i-1.5)*5+5,0);c.closePath();c.fillStyle=g;c.fill()}c.restore()}
function aquaShell(c,x,y,s){c.save();c.translate(x,y);c.scale(s,s);ellipse(c,0,5,25,8,'#143d5a60');const g=aquaLinear(c,0,-23,0,7,[[0,'#fff0e6'],[.4,'#ffacbd'],[1,'#b66a9e']]);c.beginPath();c.moveTo(0,7);c.bezierCurveTo(-12,8,-36,-9,-25,-20);c.bezierCurveTo(-18,-30,-8,-25,0,-27);c.bezierCurveTo(12,-28,25,-26,27,-13);c.bezierCurveTo(29,-5,13,7,0,7);c.fillStyle=g;c.fill();for(let i=-2;i<=2;i++)line(c,0,5,i*10,-17-Math.abs(i)*-2,'#ffe9e2aa',2);circle(c,1,-7,8,aquaLinear(c,-5,-12,7,2,[[0,'#fff'],[.45,'#f5e9ff'],[1,'#b9b9ee']]),'#fff9db',1);c.restore()}
