 for(let layer=0;layer<2;layer++){c.save();c.globalAlpha=layer?.38:.19;for(let i=0;i<Math.ceil(w/46);i++){const x=i*52+12+rng()*25,yy=h*(.78+layer*.035),r=(25+rng()*65)*s;ellipse(c,x,yy,r,r*(.55+rng()*.65),p.far);if(i%3===0)aquaCoral(c,x,yy,.55*s,p.far,i%3)}c.restore()}
