aquaSpecies.push({type:'violet',light:'#e8dbff',base:'#a38cec',dark:'#59458c',fin:'#f2bcff'},{type:'coral',light:'#ffe0c9',base:'#ff896d',dark:'#ab4862',fin:'#f9cc7d'},{type:'teal',light:'#b4fbff',base:'#39c2d2',dark:'#1f6996',fin:'#d3f7a9'});
