 if(p.type==='clown'){for(const x of [-.54,.22]){c.beginPath();c.moveTo(x-.14,-.69);c.quadraticCurveTo(x+.05,-.06,x-.15,.66);c.lineTo(x+.10,.66);c.quadraticCurveTo(x+.32,0,x+.12,-.69);c.closePath();c.fillStyle='#fff7e9';c.fill();c.strokeStyle='#903e36';c.lineWidth=.055;c.stroke()}}
