games.memory={start(api){
 const relationship=api.opts.relation||'same',pairs=[2,4,6,8,10,12,16,20].includes(Number(api.opts.pairs))?Number(api.opts.pairs):6,theme=api.opts.theme==='mixed'||pairs>12?'mixed':Object.hasOwn(memoryThemes,api.opts.theme)?api.opts.theme:'animals',info=theme==='mixed'?{title:'Miješani svijet',emoji:'🌍',tag:'Sve teme'}:memoryThemes[theme],pool=(theme==='mixed'?Object.keys(memoryThemes):[theme]).flatMap(t=>memoryThemes[t].items.map((name,index)=>({t,name,index}))),chosen=shuffle(pool).slice(0,pairs),items=Array.from({length:pairs},(_,i)=>i),relations=relationship==='same'?null:KW.learning.memoryPairs(relationship,pairs),deck=shuffle(items.flatMap(v=>[{v,side:0},{v,side:1}])).map((d,i)=>({...d,i,open:false,matched:false}));const card=d=>relations?relations[d.v][d.side]:{name:chosen[d.v].name,art:memoryIllustration(chosen[d.v].t,chosen[d.v].index,d.i)};
 let first=null,second=null,moves=0,matched=0,wait=0,done=false,lastSec=-1,preview=api.opts.memoryPeek==='yes';
 api.root.classList.add('memory-premium',`memory-${theme}`);if(api.settings.reducedMotion)api.root.classList.add('memory-still');
 api.root.innerHTML=`<div id="hud" class="game-hud"></div><div class="memory-layout"><div class="stage memory-stage"><div class="memory-board-head"><span>✦ ${relations?KW.learning.relationNames[relationship]:info.title}</span><span>${pairs} parova</span></div><div class="memory-grid" data-pairs="${pairs}" style="--cols:${pairs>=12?6:4}">${deck.map(d=>`<button type="button" class="memory-card" data-card="${d.i}" aria-label="Kartica ${d.i+1}, zatvorena"><span class="memory-inner" aria-hidden="true"><span class="memory-back"><span class="memory-back-frame">${memoryBack}</span></span><span class="memory-face"><span class="memory-illustration">${card(d).art}</span><span class="memory-face-name">${KW.escapeHTML(card(d).name)}</span><span class="memory-match-tick">✓</span></span></span></button>`).join('')}</div></div><aside class="memory-panel"><div class="memory-panel-title"><span>${info.emoji}</span><div><small>MEMORY WORLD</small><h3>${relations?KW.learning.relationNames[relationship]:info.tag}</h3></div></div><div class="memory-progress"><div><span>Pronađeni parovi</span><b id="memoryCount">0/${pairs}</b></div><div class="memory-track" role="progressbar" aria-label="Pronađeni parovi" aria-valuemin="0" aria-valuemax="${pairs}" aria-valuenow="0"><i id="memoryFill"></i></div><div class="memory-tokens" aria-hidden="true">${items.map(()=>'<i>✦</i>').join('')}</div></div><div class="memory-status" id="memoryStatus"><span id="memoryStatusIcon">✧</span><strong id="memoryStatusTitle">Pronađi par!</strong><p id="message" role="status">Otvori dvije kartice i pronađi par.</p></div><p class="memory-tip">Nema vremenskog ograničenja. Igraj svojim tempom.</p></aside></div>`;
 const buttons=$$('[data-card]',api.root),tokens=$$('.memory-tokens i',api.root);
 function draw(d){const b=buttons[d.i];b.classList.toggle('open',d.open);b.classList.toggle('matched',d.matched);b.setAttribute('aria-label',d.matched?`${card(d).name}, pronađen par`:d.open?`${card(d).name}, otvorena`:`Kartica ${d.i+1}, zatvorena`);b.disabled=d.matched}
 function status(title,msg,kind='',icon='✧'){$('#memoryStatusTitle').textContent=title;$('#memoryStatusIcon').textContent=icon;$('#memoryStatus').className='memory-status'+(kind?' '+kind:'');api.message(msg)}
 function hud(){api.hud([['Parovi',`${matched}/${pairs}`],['Potezi',moves],['Vrijeme',`${Math.floor(api.elapsed)}s`]]);$('#memoryCount').textContent=`${matched}/${pairs}`;$('#memoryFill').style.width=`${100*matched/pairs}%`;$('.memory-track',api.root).setAttribute('aria-valuenow',matched);tokens.forEach((b,i)=>b.classList.toggle('earned',i<matched))}
 function finish(completed=false){if(done)return;done=true;const score=completed?Math.max(pairs*8,pairs*25-moves*3):matched*10;api.finish({score,variant:`${theme}|${pairs}${relations?'|'+relationship:''}${api.opts.memoryPeek==='yes'?'|peek':''}${api.opts.difficulty&&api.opts.difficulty!=='normal'?'|'+api.opts.difficulty:''}`,completed,title:completed?'Pronašao si sve parove!':'Sjajan pokušaj!',detail:`${matched}/${pairs} parova · ${moves} poteza · ${Math.floor(api.elapsed)} s`})}
 function flip(i){if(api.paused||done||wait>0||preview)return;const d=deck[i];if(d.open||d.matched)return;d.open=true;draw(d);api.sound('tap');if(first===null){first=d;status('Tko mu je par?', relations?'Pronađi povezanu karticu.':'Pronađi jednaku karticu.','','?');return}second=d;moves++;if(first.v===second.v){first.matched=second.matched=true;draw(first);draw(second);first=second=null;matched++;api.sound('good');status(matched===pairs?'Svi parovi!':'Odlično!','Bravo, pronađen par!','good','★');hud();if(matched===pairs){wait=.65;return}}else{api.sound('bad');wait=({easy:1.35,normal:.85,hard:.52})[api.opts.difficulty]||.85;status('Još jedan pokušaj',relations?'Nisu par. Zapamti njihov položaj.':'Nisu isti. Zapamti njihov položaj.','retry','↻')}hud()}
 buttons.forEach((b,i)=>b.onclick=()=>flip(i));if(preview){deck.forEach(d=>{d.open=true;draw(d)});status('Zapamti kartice!','Imaš tri sekunde za pregled.')}hud();api.loop((dt,t)=>{if(preview&&t>=3){preview=false;deck.forEach(d=>{d.open=false;draw(d)});status('Pronađi par!','Sada su kartice skrivene.')}if(wait>0){wait-=dt;if(wait<=0){if(matched===pairs){finish(true);return}if(first&&second){first.open=second.open=false;draw(first);draw(second);first=second=null;status('Pronađi par!','Pokušaj ponovno!')}}}if(Math.floor(t)!==lastSec){lastSec=Math.floor(t);hud()}});return{finish:()=>finish(matched===pairs)};
}};

